from pathlib import Path
import json,subprocess,hashlib
R=Path(__file__).resolve().parents[1];Q=json.loads((R/'qa-spec.json').read_text());L=json.loads((R/'source/layout.json').read_text());out=R/'validation/native-extrema';out.mkdir(exist_ok=True);rows=[]
for room in Q['rooms']:
 data=dict(**room,grid=L['collision'],width=len(L['collision'][0]),height=len(L['collision']));inp=out/(room['id']+'-input.json');dest=out/(room['id']+'-report.json');inp.write_text(json.dumps(data,indent=2)+'\n');subprocess.run(['node',str(R/'tools/native-all-cells.cjs'),str(inp),str(dest)],check=True,cwd=R);r=json.loads(dest.read_text());rows.append(dict(room=room['id'],physicalRegion=room['physicalRegion'],legs=r['legs'],samples=r['samples'],pass_=r['pass'],inputSHA256=hashlib.sha256(inp.read_bytes()).hexdigest(),reportSHA256=hashlib.sha256(dest.read_bytes()).hexdigest()))
report=dict(scope='Author source-native pinned replay over every admitted cell at center/fitted extrema, every actual randomized initial spawn outcome and ordered target/return legs across two disjoint physical regions. Stubbed scene, not browser/mobile/engine acceptance.',regions=rows,legs=sum(r['legs']for r in rows),samples=sum(r['samples']for r in rows),pass_=all(r['pass_']for r in rows));(R/'validation/native-extrema-summary.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
